-- Codex CyE, 22/10/2026. Solo lectura sobre wingstest. No repetir operaciones del club.
SET TRANSACTION READ ONLY;
START TRANSACTION WITH CONSISTENT SNAPSHOT;
SELECT 'CAJA_2' AS seccion;
SELECT id,usuario_operativo_id,apertura_at,cierre_at,estado,caja_origen_id,efectivo_heredado,efectivo_inicial,efectivo_esperado,efectivo_contado,diferencia_efectivo,cambio_retenido,efectivo_retirado,usuario_admin_validacion_id,validada_at FROM cajas_operativas WHERE id=2;
SELECT 'MOVIMIENTOS_CAJA_2' AS seccion;
SELECT m.id,m.fecha,m.alumno_id,m.pago_id,m.tipo_caja_id,t.abreviatura,s.nombre,r.tipo,m.monto,m.estado,m.usuario_id,m.reporte_clasificacion,m.verificado_at,m.verificado_por,m.observaciones FROM movimientos_operativos m JOIN tipos_caja t ON t.id=m.tipo_caja_id JOIN subrubros s ON s.id=m.subrubro_id JOIN rubros r ON r.id=s.rubro_id WHERE m.caja_operativa_id=2 ORDER BY m.id;
SELECT 'PAGOS_5_A_9' AS seccion;
SELECT p.id,p.alumno_id,a.nombre,a.apellido,p.fecha_pago,p.mes,p.anio,p.monto_final,p.estado FROM pagos p JOIN alumnos a ON a.id=p.alumno_id WHERE p.id BETWEEN 5 AND 9 ORDER BY p.id;
SELECT 'IMPUTACIONES_5_A_9' AS seccion;
SELECT p.id AS pago_id,d.id AS deuda_id,d.alumno_id,d.periodo,pd.monto_aplicado,d.monto_original,d.monto_pagado,d.estado FROM pagos p JOIN pago_deuda_cuota pd ON pd.pago_id=p.id JOIN deuda_cuotas d ON d.id=pd.deuda_cuota_id WHERE p.id BETWEEN 5 AND 9 ORDER BY p.id,d.periodo;
SELECT 'REFLEJOS_CAJA_2' AS seccion;
SELECT c.id,c.movimiento_operativo_id,c.referencia_tipo,c.referencia_id,c.fecha,c.tipo_caja_id,c.monto,c.reporte_tipo,c.reporte_clasificacion,c.anulado_at FROM cashflow_movimientos c WHERE c.movimiento_operativo_id IN (SELECT id FROM movimientos_operativos WHERE caja_operativa_id=2) ORDER BY c.movimiento_operativo_id,c.id;
SELECT 'CONTROL_REFLEJOS' AS seccion;
SELECT m.id,COUNT(c.id) AS reflejos,SUM(CASE WHEN c.monto=(CASE WHEN m.reporte_tipo='EGRESO' THEN -ABS(m.monto) ELSE ABS(m.monto) END) AND c.tipo_caja_id=m.tipo_caja_id AND c.fecha=m.fecha AND c.reporte_clasificacion=m.reporte_clasificacion THEN 1 ELSE 0 END) AS iguales FROM movimientos_operativos m LEFT JOIN cashflow_movimientos c ON c.movimiento_operativo_id=m.id WHERE m.caja_operativa_id=2 GROUP BY m.id ORDER BY m.id;
SELECT 'CONTROL_SUMAS_PAGOS' AS seccion;
SELECT p.id,p.monto_final,SUM(pd.monto_aplicado) AS imputado FROM pagos p JOIN pago_deuda_cuota pd ON pd.pago_id=p.id WHERE p.id BETWEEN 5 AND 9 GROUP BY p.id ORDER BY p.id;
SELECT 'ALUMNOS_AFECTADOS' AS seccion;
SELECT id,nombre,apellido,dni,fecha_nacimiento,fecha_alta,grupo_id,deporte_id,activo,nombre_tutor,telefono_tutor FROM alumnos WHERE id IN (241,245,246,270,331,333,341) ORDER BY id;
SELECT 'PLANES_MORA_JULIETA' AS seccion;
SELECT ap.alumno_id,ap.id,ap.plan_id,ap.fecha_desde,ap.fecha_hasta,ap.activo,gp.grupo_id,gp.clases_por_semana,gp.precio_mensual FROM alumno_planes ap JOIN grupo_planes gp ON gp.id=ap.plan_id WHERE ap.alumno_id IN (331,341) ORDER BY ap.alumno_id,ap.id;
SELECT 'DEUDAS_AFECTADAS' AS seccion;
SELECT id,alumno_id,periodo,monto_original,monto_pagado,estado FROM deuda_cuotas WHERE alumno_id IN (241,245,246,270,331,333,341) AND periodo BETWEEN '2026-09' AND '2026-11' ORDER BY alumno_id,periodo,id;
SELECT 'CARGOS_AFECTADOS' AS seccion;
SELECT id,alumno_id,tipo,monto_original,monto_condonado,estado FROM cargos_alumno WHERE alumno_id IN (241,331,341) ORDER BY alumno_id,id;
SELECT 'ASISTENCIAS_28_74' AS seccion;
SELECT c.id AS clase_id,c.grupo_id,c.fecha,a.id AS alumno_id,a.nombre,a.apellido,asi.presente FROM clases c JOIN asistencias asi ON asi.clase_id=c.id JOIN alumnos a ON a.id=asi.alumno_id WHERE c.id IN (28,74) ORDER BY c.id,a.apellido,a.nombre;
SELECT 'SIN_MARCAS_CLASE_6' AS seccion;
SELECT c.id,c.fecha,c.grupo_id,COUNT(a.id) AS marcas FROM clases c LEFT JOIN asistencias a ON a.clase_id=c.id WHERE c.id=6 GROUP BY c.id;
SELECT 'DUPLICADOS_ASISTENCIA' AS seccion;
SELECT clase_id,alumno_id,COUNT(*) AS n FROM asistencias WHERE clase_id IN (28,74) GROUP BY clase_id,alumno_id HAVING COUNT(*)>1;
SELECT 'MATRICULA_ACTUAL' AS seccion;
SELECT deporte_id,grupo_id,COUNT(*) AS activos FROM alumnos WHERE activo=1 GROUP BY deporte_id,grupo_id ORDER BY deporte_id,grupo_id;
SELECT 'TOTALES_ASISTENCIAS' AS seccion;
SELECT clase_id,COUNT(*) AS registros,SUM(presente=1) AS presentes,SUM(presente=0) AS ausentes FROM asistencias WHERE clase_id IN (6,28,74) GROUP BY clase_id ORDER BY clase_id;
SELECT 'SALDOS_INICIALES' AS seccion;
SELECT id,nombre,abreviatura,saldo_inicial FROM tipos_caja ORDER BY id;
SELECT 'CASHFLOW_OCTUBRE' AS seccion;
SELECT c.id,c.fecha,c.movimiento_operativo_id,c.tipo_caja_id,c.monto,c.reporte_tipo,c.reporte_clasificacion,c.referencia_tipo,c.referencia_id FROM cashflow_movimientos c WHERE c.fecha BETWEEN '2026-10-01' AND '2026-10-13' ORDER BY c.id;
SELECT 'SALDOS_POR_MEDIO' AS seccion;
SELECT t.id,t.abreviatura,t.saldo_inicial,COALESCE(SUM(c.monto),0) AS movimientos,t.saldo_inicial+COALESCE(SUM(c.monto),0) AS saldo FROM tipos_caja t LEFT JOIN cashflow_movimientos c ON c.tipo_caja_id=t.id AND c.fecha<='2026-10-13' LEFT JOIN subrubros s ON s.id=c.subrubro_id LEFT JOIN rubros r ON r.id=s.rubro_id GROUP BY t.id ORDER BY t.id;
SELECT 'CUOTAS_POR_PERIODO_PAGADO' AS seccion;
SELECT d.periodo,SUM(pd.monto_aplicado) AS cobrado FROM pago_deuda_cuota pd JOIN pagos p ON p.id=pd.pago_id JOIN deuda_cuotas d ON d.id=pd.deuda_cuota_id WHERE p.estado='COMPLETADO' AND p.fecha_pago BETWEEN '2026-10-01' AND '2026-10-13' GROUP BY d.periodo ORDER BY d.periodo;
SELECT 'PAGOS_CARGOS_ESQUEMA' AS seccion;
SHOW COLUMNS FROM pago_cargo_alumno;
SELECT 'DEUDA_CUOTAS_ACTIVOS' AS seccion;
SELECT SUM(GREATEST(d.monto_original-d.monto_pagado,0)) AS deuda FROM deuda_cuotas d JOIN alumnos a ON a.id=d.alumno_id WHERE a.activo=1 AND d.estado IN ('PENDIENTE','AJUSTADA') AND d.periodo<='2026-10';
SELECT 'EVENTOS_MORA_Y_NOVIEMBRE' AS seccion;
SELECT tipo,origen_id,deuda_cuota_id,periodo,persona_id,fecha,delta_centavos,motivo FROM reporte_eventos WHERE persona_id IN (331,341) AND fecha='2026-10-13' ORDER BY id;
SELECT 'CARGOS_Y_PAGOS_POR_PERSONA' AS seccion;
SELECT c.id,c.alumno_id,c.tipo,c.monto_original,c.monto_condonado,COALESCE(SUM(CASE WHEN p.estado='COMPLETADO' THEN pc.monto_aplicado ELSE 0 END),0) AS pagado,c.estado FROM cargos_alumno c LEFT JOIN pago_cargo_alumno pc ON pc.cargo_alumno_id=c.id LEFT JOIN pagos p ON p.id=pc.pago_id WHERE c.alumno_id IN (241,331,341) GROUP BY c.id ORDER BY c.id;
SELECT 'CARGOS_PENDIENTES_ACTIVOS' AS seccion;
SELECT c.id,c.alumno_id,c.tipo,GREATEST(c.monto_original-c.monto_condonado-COALESCE((SELECT SUM(pc.monto_aplicado) FROM pago_cargo_alumno pc JOIN pagos p ON p.id=pc.pago_id WHERE pc.cargo_alumno_id=c.id AND p.estado='COMPLETADO'),0),0) AS saldo FROM cargos_alumno c JOIN alumnos a ON a.id=c.alumno_id WHERE a.activo=1 AND c.estado='VIGENTE' HAVING saldo>0 ORDER BY c.id;
SELECT 'INSCRIPCIONES_COBRADAS_OCTUBRE' AS seccion;
SELECT pc.pago_id,c.alumno_id,c.tipo,pc.monto_aplicado FROM pago_cargo_alumno pc JOIN pagos p ON p.id=pc.pago_id JOIN cargos_alumno c ON c.id=pc.cargo_alumno_id WHERE p.estado='COMPLETADO' AND p.fecha_pago BETWEEN '2026-10-01' AND '2026-10-13' ORDER BY pc.id;
SELECT 'SIN_ASISTENCIA_POR_FECHA' AS seccion;
SELECT c.fecha,COUNT(*) AS sin_asistencia FROM clases c WHERE c.cancelada=0 AND c.fecha<'2026-10-13' AND NOT EXISTS (SELECT 1 FROM asistencias a WHERE a.clase_id=c.id) GROUP BY c.fecha ORDER BY c.fecha;
COMMIT;
